        AEMSegmentAddINTERPOLATION_DEGREE(builder, self.INTERPOLATION_DEGREE)
        if self.ATTITUDE_DATA_LINES is not None:
            AEMSegmentAddATTITUDE_DATA_LINES(builder, ATTITUDE_DATA_LINES)
        AEMSegment = AEMSegmentEnd(builder)
        return AEMSegment
